          "switchFlag": 0
        }
      }
    }
  ],
  "dataModelSchema": {
    "lighting": {
      "title": {
        "type": "string",
        "description": "智能照明设备名称",
        "sampleValue": "吸顶灯"
      },
      "stateText": {
        "type": "string",
        "description": "当前灯光开关状态提示",
        "sampleValue": "待开启"
      },
      "hint": {
        "type": "string",
        "description": "开灯动作的简短提示",
        "sampleValue": "点按开灯"
      },
      "buttonLabel": {
        "type": "string",
        "description": "开灯按钮文案",
        "sampleValue": "开灯"
      }
    },
    "asset": {
      "lampIcon": {
        "type": "string",
        "description": "吸顶灯亮起图标素材路径",
        "sampleValue": "resources/base/media/lamp_ceiling_light.svg"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/lamp_ceiling_light.svg",
      "description": "吸顶灯亮起图标，适合用于智能照明开灯动作和灯光状态识别。",
      "bindTo": "/asset/lampIcon"
    }
  ]
}

